def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def hidden_rule_fn(state):
    # Append one element to the state
    new_index = len(state)

    if new_index < 2:
        # Should not happen based on training data (all states have at least 2 elements)
        # Fallback: just return state appended with 0
        return state + [0]

    last_two = state[-2:]

    if is_prime(new_index):
        # ploon-XOR: bitwise XOR of two kreels, then mod 7
        new_val = (last_two[0] ^ last_two[1]) % 7
    else:
        # grolp-sum: arithmetic sum of two kreels plus 3, then mod 7
        new_val = (last_two[0] + last_two[1] + 3) % 7

    return state + [new_val]
